#define WH_Thanks 1
#define WH_Healthy 2
#define WH_SurfPlaces 3
#define WH_ComingHome 4
#define WH_EverGrande 5
#define WH_Wonder 6
#define WH_MomHappy 7
#define WH_HusbandGift 8
#define WH_LeftWithout 9

#ifdef HOENN_EMERALD
// Emerald (emerald_ch0_3; pokeemerald PetalburgCity_WallysHouse): Surf is given right after Wally's father brings the player here
// (Petalburg's walk, scenes/emerald/PetalburgCity.inc, VAR_PETALBURG_STATE 4): the player arrives in front of him (Em_WH_Arrive),
// he apologises for the trouble, hands over HM03 and VAR_PETALBURG_STATE becomes 5. Talking to him later: the other lines.
Em_WH_Arrive:
    h_lock
    FadeInBlack                             // (the walk's scripted warp leaves the screen black)
    FadeWait
    h_turnobject 255, 3                     // PlayerWallysDadFaceEachOther: east / west
    h_turnobject 1, 2
    h_buffer_player
    VMCall Sub_WH_EmGiveSurf
    h_release

Sub_WH_EmGiveSurf:                          // PetalburgCity_WallysHouse_EventScript_GiveHMSurf
    h_msgbox_actor WH_Healthy, 1            // <player>! Please excuse us for dragging you here this way. ... I'd really like you to have this.
    h_closemessage                          // (Black 2: the item script opens its own window)
    h_giveitem ITEM_HM03                    // giveitem ITEM_HM03_SURF (Black 2's HM03 is Surf)
    h_goto_if_eq HLIB_RESULT, 0, L_WH_EmNoSurf
    h_setflag FLAG_RECEIVED_HM_SURF
    h_msgbox_actor WH_SurfPlaces, 1         // If your Pokémon can Surf, you'll be able to go to all sorts of places.
    h_setvar VAR_PETALBURG_STATE, 5
L_WH_EmNoSurf:                              // (a full Bag: state 4 stays and talking to him gives it again)
    VMReturn

Story_WH_WallysDad:                         // PetalburgCity_WallysHouse_EventScript_WallysDad
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_buffer_player
    h_goto_if_set FLAG_DEFEATED_WALLY_VICTORY_ROAD, L_WH_EmEverGrande
    h_goto_if_set FLAG_RECEIVED_HM_SURF, L_WH_EmReceivedSurf
    h_goto_if_eq VAR_PETALBURG_STATE, 4, L_WH_EmGiveSurf
    h_goto_if_set FLAG_THANKED_FOR_PLAYING_WITH_WALLY, L_WH_EmPlayedWithWally
    h_msgbox WH_Thanks                      // You're... Ah, you must be <player>, right? ...
    h_setflag FLAG_THANKED_FOR_PLAYING_WITH_WALLY
    h_release
L_WH_EmGiveSurf:
    VMCall Sub_WH_EmGiveSurf
    h_release
L_WH_EmEverGrande:
    h_msgbox WH_EverGrande                  // Oh? You met Wally in Ever Grande City? ...
    h_release
L_WH_EmReceivedSurf:
    h_msgbox WH_ComingHome                  // Wally's coming home soon. I'm looking forward to that.
    h_release
L_WH_EmPlayedWithWally:
    h_msgbox WH_Wonder                      // I wonder how our Wally is doing?
    h_release

Story_WH_WallysMom:                         // PetalburgCity_WallysHouse_EventScript_WallysMom
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_buffer_player
    h_goto_if_set FLAG_RECEIVED_HM_SURF, L_WH_EmMomReceivedSurf
    h_msgbox WH_MomHappy                    // Wally was really happy when he told us that he caught a Pokémon. ...
    h_release
L_WH_EmMomReceivedSurf:
    h_msgbox WH_LeftWithout                 // I want you to keep this a secret from my husband... ...
    h_release
#else
